try {
  const parsedData = JSON.parse($input.first().json.output);
  return {
    json: {
      status: "success",
      adatok: parsedData
    }
  };
} catch (e) {
  return {
    json: {
      status: "error",
      hiba: "Nem érvényes JSON",
      nyers_szoveg: $input.first().json.output
    }
  };
}

